// Support Ops Copilot (watsonx Orchestrate) embedded as a floating chat.
// Values come from /static/copilot-config.json, generated by
// orchestrate/make_copilot_embed.py. If the file is missing, nothing loads.
(function () {
  if (window.__copilotEmbedLoaded) return;
  window.__copilotEmbedLoaded = true;

  fetch('/static/copilot-config.json', { cache: 'no-store' })
    .then(function (res) { return res.ok ? res.json() : null; })
    .then(function (cfg) {
      if (!cfg || !cfg.agentId || !cfg.orchestrationID || !cfg.hostURL) return;

      var conf = {
        orchestrationID: cfg.orchestrationID,
        hostURL: cfg.hostURL,
        showLauncher: true,
        defaultLocale: cfg.locale || 'en',
        chatOptions: { agentId: cfg.agentId },
        layout: { form: 'float', width: '420px', height: '640px' },
        header: { showMaximize: true }
      };
      if (cfg.deploymentPlatform) conf.deploymentPlatform = cfg.deploymentPlatform;
      if (cfg.crn) conf.crn = cfg.crn;
      if (cfg.agentEnvironmentId) conf.chatOptions.agentEnvironmentId = cfg.agentEnvironmentId;
      window.wxOConfiguration = conf;

      var script = document.createElement('script');
      script.src = cfg.hostURL.replace(/\/$/, '') + '/wxochat/wxoLoader.js?embed=true';
      script.addEventListener('load', function () { wxoLoader.init(); });
      document.head.appendChild(script);
    })
    .catch(function (err) { console.warn('[copilot] embed not loaded', err); });
})();
